//-----------------------------------------------------------------------------
// find_max
//-----------------------------------------------------------------------------
//
// Given a non‐empty slice `a`, returns some index `i` such that
//   0 <= i < a.len()
// and for all j in 0..a.len(), a[j] <= a[i].
//
// The implementation walks the slice from 1..len, keeping track of a
// `max_idx`.  We supply a loop‐invariant and a decreases‐measure to
// enable verification.

#[requires(a.len() > 0)]
#[ensures(result < a.len())]
#[ensures(forall(|j: usize| j < a.len() ==> a[j] <= a[result]))]
pub fn find_max(a: &[i32]) -> usize {
    // Since the problem guarantees a is non-empty, we can safely
    // initialize max_idx to 0.
    let mut max_idx: usize = 0;
    // Invariant facts at this point:
    //   0 < 1  ==>  max_idx < 1
    // and
    //   forall j < 1 : a[j] <= a[max_idx].
    //
    // Iterate over the slice starting from index 1
    #[invariant(i <= a.len())]
    #[invariant(max_idx < i)]
    #[invariant(forall(|j: usize| j < i ==> a[j] <= a[max_idx]))]
    #[decreases(a.len() - i)]
    for (i, &val) in a.iter().enumerate().skip(1) {
        if val > a[max_idx] {
            max_idx = i;
        }
    }

    // At loop exit `i == a.len()`, so the invariants give:
    //   max_idx < a.len()
    // and
    //   forall j < a.len() : a[j] <= a[max_idx].
    max_idx
}

